<?php
require dirname(__DIR__).'/includes/bootstrap.php'; require_permission('refunds.manage'); $bid=current_branch_id();
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $action=$_POST['_action']??'request';
 if($action==='request'){ try{db()->beginTransaction(); $saleId=(int)$_POST['sale_id']; $sale=one('SELECT * FROM sales WHERE id=? AND branch_id=?',[$saleId,$bid]); if(!$sale) throw new RuntimeException('Sale not found.'); $amount=0;$items=[]; foreach($_POST['sale_item_id']??[] as $sid){$sid=(int)$sid;$qty=(float)($_POST['qty_'.$sid]??0); if($qty<=0)continue; $it=one('SELECT * FROM sale_items WHERE id=? AND sale_id=?',[$sid,$saleId]); if(!$it)continue; $reserved=amount_refunded_for_item($sid); $max=(float)$it['quantity']-(float)$it['refunded_quantity']-$reserved; if($qty>$max+0.001) throw new RuntimeException('Refund quantity is greater than remaining quantity for '.$it['description']); $line=((float)$it['line_total']/(float)$it['quantity'])*$qty; $amount+=$line; $items[]=[$sid,$qty,$line,isset($_POST['restock_'.$sid])?1:0]; }
 if(!$items) throw new RuntimeException('Select refund items.'); $no=next_code('REF','refunds','refund_no'); q('INSERT INTO refunds(branch_id,refund_no,sale_id,refund_type,requested_amount,reason,status,requested_by,created_at) VALUES(?,?,?,?,?,?,"pending",?,NOW())',[$bid,$no,$saleId,$_POST['refund_type']??'partial',$amount,trim($_POST['reason']),$_SESSION['user_id']]); $rid=(int)db()->lastInsertId(); foreach($items as $it) q('INSERT INTO refund_items(refund_id,sale_item_id,quantity,amount,restock) VALUES(?,?,?,?,?)',[$rid,$it[0],$it[1],$it[2],$it[3]]); audit('create','refunds',$rid); db()->commit(); flash('success','Refund request created.');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack(); flash('error',$e->getMessage());} redirect('modules/refunds.php'); }
 if(in_array($action,['approve','reject','complete'],true)){ $rid=(int)$_POST['id']; $r=one('SELECT * FROM refunds WHERE id=? AND branch_id=?',[$rid,$bid]); if(!$r){flash('error','Refund not found.'); redirect('modules/refunds.php');} try{db()->beginTransaction(); if($action==='approve'){q('UPDATE refunds SET status="approved",approved_amount=requested_amount,approved_by=? WHERE id=?',[$_SESSION['user_id'],$rid]);}
 elseif($action==='reject'){q('UPDATE refunds SET status="rejected",approved_by=? WHERE id=?',[$_SESSION['user_id'],$rid]);}
 else { if(!in_array($r['status'],['pending','approved'],true)) throw new RuntimeException('Refund already completed or closed.'); $items=all('SELECT ri.*,si.item_type,si.item_id,si.description,si.sale_id FROM refund_items ri JOIN sale_items si ON si.id=ri.sale_item_id WHERE ri.refund_id=?',[$rid]); foreach($items as $it){ q('UPDATE sale_items SET refunded_quantity=refunded_quantity+? WHERE id=?',[$it['quantity'],$it['sale_item_id']]); if($it['restock'] && $it['item_type']==='product') stock_move($bid,(int)$it['item_id'],(float)$it['quantity'],'refund','refund',$rid,'Product returned'); }
     q('UPDATE commissions SET status="reversed" WHERE sale_id=? AND status="unpaid"',[$r['sale_id']]); $cust=scalar('SELECT customer_id FROM sales WHERE id=?',[$r['sale_id']]); if($cust){$acc=ensure_loyalty_account((int)$cust); $reversal=(int)floor((float)$r['requested_amount']/max(1,(float)setting('loyalty_spend_per_point',1000,$bid))); if($reversal>0){q('UPDATE loyalty_accounts SET points_balance=GREATEST(points_balance-?,0),updated_at=NOW() WHERE id=?',[$reversal,$acc]); q('INSERT INTO loyalty_transactions(account_id,sale_id,transaction_type,points,description,created_by,created_at) VALUES(?,?,"refund",?,?,?,NOW())',[$acc,$r['sale_id'],-$reversal,'Points reversed after refund',$_SESSION['user_id']]);}}
     q('UPDATE refunds SET status="completed",approved_amount=requested_amount,approved_by=?,payment_method=?,completed_at=NOW() WHERE id=?',[$_SESSION['user_id'],$_POST['payment_method']??'cash',$rid]); q('UPDATE sales SET status="partially_refunded" WHERE id=?',[$r['sale_id']]); }
   audit('update','refunds',$rid,['action'=>$action]); db()->commit(); flash('success','Refund updated.'); }catch(Throwable $e){if(db()->inTransaction())db()->rollBack(); flash('error',$e->getMessage());} redirect('modules/refunds.php'); }
}
$saleId=(int)($_GET['sale_id']??0); $sale=$saleId?one('SELECT * FROM sales WHERE id=? AND branch_id=?',[$saleId,$bid]):null; $saleItems=$sale?all('SELECT * FROM sale_items WHERE sale_id=?',[$saleId]):[]; $rows=all('SELECT r.*,s.invoice_no,c.full_name customer FROM refunds r JOIN sales s ON s.id=r.sale_id LEFT JOIN customers c ON c.id=s.customer_id WHERE r.branch_id=? ORDER BY r.id DESC',[$bid]); $title='Refund Management'; $subtitle='Partial/full refunds with approval, audit log, stock return and commission reversal.'; include dirname(__DIR__).'/includes/header.php';?>
<div class="toolbar"><form><input name="sale_id" placeholder="Sale ID" value="<?=e($saleId?:'')?>"><button class="btn light">Load Sale</button></form></div><?php if($sale):?><section class="card"><h2>Request Refund for <?=e($sale['invoice_no'])?></h2><form method="post"><?=csrf_field()?><input type="hidden" name="_action" value="request"><input type="hidden" name="sale_id" value="<?=e($saleId)?>"><div class="form-grid"><div class="form-group"><label>Type</label><select name="refund_type"><option value="partial">Partial</option><option value="full">Full</option></select></div><div class="form-group full"><label>Reason</label><textarea name="reason" required></textarea></div></div><table><thead><tr><th>Refund</th><th>Item</th><th>Sold</th><th>Already Refunded</th><th>Quantity to Refund</th><th>Restock</th></tr></thead><tbody><?php foreach($saleItems as $it):?><tr><td><input type="checkbox" name="sale_item_id[]" value="<?=e($it['id'])?>"></td><td><?=e($it['description'])?></td><td><?=e($it['quantity'])?></td><td><?=e($it['refunded_quantity'])?></td><td><input type="number" step="0.01" name="qty_<?=e($it['id'])?>" value="0"></td><td><input type="checkbox" name="restock_<?=e($it['id'])?>" value="1" <?= $it['item_type']==='product'?'':'disabled'?>></td></tr><?php endforeach;?></tbody></table><button class="btn">Create Refund Request</button></form></section><?php endif;?><div class="table-wrap"><table><thead><tr><th>Date</th><th>No.</th><th>Invoice</th><th>Customer</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['refund_no'])?></td><td><?=e($r['invoice_no'])?></td><td><?=e($r['customer'])?></td><td><?=money($r['requested_amount'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='pending'):?><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($r['id'])?>"><button class="btn small secondary" name="_action" value="approve">Approve</button><button class="btn small danger" name="_action" value="reject">Reject</button></form><?php endif;if(in_array($r['status'],['pending','approved'])):?><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($r['id'])?>"><select name="payment_method"><?php foreach(payment_methods() as $m=>$l): if($m==='gift_card')continue;?><option value="<?=e($m)?>"><?=e($l)?></option><?php endforeach;?></select><button class="btn small success" name="_action" value="complete">Complete</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php include dirname(__DIR__).'/includes/footer.php'; ?>